package com.flippingfriend.companion;
/** Immutable non-authorizing strategy inputs for later exact-remainder price evaluation. */
final class BuyReplacementPricingStrategyContext {
 private final BuyReplacementPricingContext source; private final String appetiteName; private final double[] buyOffsets; private final double effectiveHorizonHours;
 BuyReplacementPricingStrategyContext(BuyReplacementPricingContext s,String n,double[] o,double h){source=s;appetiteName=n;buyOffsets=o.clone();effectiveHorizonHours=h;}
 String getReadinessAssessmentId(){return source.getReadinessAssessmentId();} String getReadinessPolicyVersion(){return source.getReadinessPolicyVersion();} String getIntentId(){return source.getIntentId();} String getOriginalOfferIdentity(){return source.getOriginalOfferIdentity();} String getRecommendationId(){return source.getRecommendationId();} int getSlot(){return source.getSlot();} int getItemId(){return source.getItemId();} String getItemName(){return source.getItemName();} int getExactRemainderQuantity(){return source.getExactRemainderQuantity();} int getHistoricalOriginalPrice(){return source.getHistoricalOriginalPrice();} int getCurrentLowPrice(){return source.getCurrentLowPrice();} int getCurrentHighPrice(){return source.getCurrentHighPrice();} int getBuyLimitRemaining(){return source.getBuyLimitRemaining();} long getSpendableCoins(){return source.getSpendableCoins();} boolean isMembers(){return source.isMembers();} long getIntentCreatedAt(){return source.getIntentCreatedAt();} long getIntentExpiresAt(){return source.getIntentExpiresAt();} long getAccountObservedAt(){return source.getAccountObservedAt();} long getMarketObservedAt(){return source.getMarketObservedAt();} long getInputObservedAt(){return source.getInputObservedAt();} long getEvaluatedAt(){return source.getEvaluatedAt();} String getAppetiteName(){return appetiteName;} double[] getBuyOffsets(){return buyOffsets.clone();} double getEffectiveHorizonHours(){return effectiveHorizonHours;}
}
